import{_ as s,o as c,c as a}from"./chunks/framework.D4oetGi0.js";const m=JSON.parse('{"title":"Kubernetes 应用部署与配置实践","titleTemplate":":title · 知行笔记","description":"发布前确认环境 下列命令中的 demo 是示例命名空间，操作前替换为实际值。先检查当前集群和权限，避免把测试配置应用到生产集群。 Ubuntu、RHEL系与CentOS 7管理机上的kubectl操作按同样流程执行，清单字段取决于服务端AP","frontmatter":{"title":"Kubernetes 应用部署与配置实践","titleTemplate":":title · 知行笔记","description":"发布前确认环境 下列命令中的 demo 是示例命名空间，操作前替换为实际值。先检查当前集群和权限，避免把测试配置应用到生产集群。 Ubuntu、RHEL系与CentOS 7管理机上的kubectl操作按同样流程执行，清单字段取决于服务端AP","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"category\\":\\"容器运维\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">容器运维\\\\u003c/div>\\\\u003ch1>Kubernetes 应用部署与配置实践\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 24 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">kubernetes\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">deployment\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">service\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">troubleshooting\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003ch2 id=\\\\\\"发布前确认环境\\\\\\">发布前确认环境\\\\u003c/h2>\\\\n\\\\u003cp>下列命令中的 \\\\u003ccode>demo\\\\u003c/code> 是示例命名空间，操作前替换为实际值。先检查当前集群和权限，避免把测试配置应用到生产集群。\\\\u003c/p>\\\\n\\\\u003cp>Ubuntu、RHEL系与CentOS 7管理机上的kubectl操作按同样流程执行，清单字段取决于服务端API版本；不因本机系统旧就改用过期API。CentOS 7先确认kubectl/Helm二进制可运行且版本适配集群；不兼容时改在受维护的管理机执行，节点内核及运行时检查见\\\\u003ca href=\\\\\\"kubernetes-cluster-troubleshooting.html\\\\\\">集群维护\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 显示当前 kubectl 上下文\\\\u003c/span>\\\\nkubectl config current-context\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看客户端和服务端版本\\\\u003c/span>\\\\nkubectl version\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查当前身份能否在目标命名空间创建 Deployment\\\\u003c/span>\\\\nkubectl auth can-i create deployments -n demo\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003ch2 id=\\\\\\"清单字段不熟悉时直接查集群支持的-api\\\\\\">清单字段不熟悉时，直接查集群支持的 API\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看集群提供的资源类型及其 API 组\\\\u003c/span>\\\\nkubectl api-resources\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询 Deployment 探针字段的结构，按实际字段继续展开\\\\u003c/span>\\\\nkubectl explain deployment.spec.template.spec.containers.readinessProbe\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 生成 Deployment 草稿，输出到新文件，不创建资源\\\\u003c/span>\\\\nkubectl create deployment demo-api --image=nginx:stable-alpine --dry-run=client -o yaml &gt; demo-api-draft.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 在命名空间已存在时，让服务端验证清单及准入规则，不保存对象\\\\u003c/span>\\\\nkubectl apply --dry-run=server -n demo -f demo-api-draft.yaml\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>\\\\u003ccode>&gt;\\\\u003c/code> 将输出写入文件，同名文件存在时会覆盖，先确认文件名；\\\\u003ccode>--dry-run=client\\\\u003c/code> 不验证所有服务端规则，\\\\u003ccode>--dry-run=server\\\\u003c/code> 还需要集群连接和对应权限。不要把旧清单中的 apps/v1beta1 或 extensions/v1beta1 直接用于不支持这些版本的集群。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"资源对象怎么选择\\\\\\">资源对象怎么选择\\\\u003c/h2>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>需求\\\\u003c/th>\\\\n\\\\u003cth>对象与检查重点\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>常驻无状态服务\\\\u003c/td>\\\\n\\\\u003ctd>Deployment；副本、探针和更新策略\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>每节点运行采集器或代理\\\\u003c/td>\\\\n\\\\u003ctd>DaemonSet；节点选择、污点容忍和更新覆盖率\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>执行一次的任务\\\\u003c/td>\\\\n\\\\u003ctd>Job；完成条件、失败重试和任务幂等\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>周期任务\\\\u003c/td>\\\\n\\\\u003ctd>CronJob；时区、并发策略、错过调度和历史保留\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>固定身份和独立存储\\\\u003c/td>\\\\n\\\\u003ctd>StatefulSet；稳定网络身份、PVC 和有序更新\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>控制器保持副本数量，不保证业务绝不宕机。两个副本若落在同一故障域，仍可能同时不可用；生产应用应结合反亲和、拓扑分布和容量规划。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"运行一个完整的-web-示例\\\\\\">运行一个完整的 Web 示例\\\\u003c/h2>\\\\n\\\\u003cp>前提：已有可用集群、kubectl 和创建命名空间的权限。保存下面内容为 \\\\u003ccode>demo-web.yaml\\\\u003c/code>。镜像版本仅作演示，部署前按仓库可用版本和安全要求调整。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-yaml\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建独立的演示命名空间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">Namespace\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-meta\\\\\\">---\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 通过配置文件提供静态首页\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">ConfigMap\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web-content\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">namespace:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">data:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">index.html:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">|\\\\n    &lt;h1&gt;Hello Kubernetes&lt;/h1&gt;\\\\n\\\\u003c/span>\\\\u003cspan class=\\\\\\"hljs-meta\\\\\\">---\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 由 Deployment 管理两个副本\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">apps/v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">Deployment\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">namespace:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">spec:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">replicas:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">2\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">selector:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">matchLabels:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">app:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">strategy:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">type:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">RollingUpdate\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">rollingUpdate:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">maxSurge:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">1\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">maxUnavailable:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">0\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">template:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">labels:\\\\u003c/span>\\\\n        \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">app:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">spec:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">terminationGracePeriodSeconds:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">30\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">containers:\\\\u003c/span>\\\\n        \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">web\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">image:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">nginx:stable-alpine\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">ports:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">containerPort:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">80\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">resources:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">requests:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">cpu:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">100m\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">memory:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">64Mi\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">limits:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">cpu:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">500m\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">memory:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">128Mi\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">startupProbe:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">httpGet:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">path:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">port:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">failureThreshold:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">30\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">periodSeconds:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">2\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">readinessProbe:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">httpGet:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">path:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">port:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">periodSeconds:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">5\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">livenessProbe:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">httpGet:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">path:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">port:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">periodSeconds:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">10\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">volumeMounts:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">content\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">mountPath:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/usr/share/nginx/html\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">readOnly:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">volumes:\\\\u003c/span>\\\\n        \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">content\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">configMap:\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web-content\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-meta\\\\\\">---\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 集群内部通过 Service 访问应用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">Service\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">namespace:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">spec:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">selector:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">app:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">ports:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">port:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">80\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">targetPort:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">http\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>执行顺序：校验 → 应用 → 等待就绪 → 检查端点 → 转发本地端口 → HTTP 验证。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅解析和生成对象，不写入集群\\\\u003c/span>\\\\nkubectl apply --dry-run=client -f demo-web.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建命名空间、配置和应用；会修改当前集群\\\\u003c/span>\\\\nkubectl apply -f demo-web.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待 Deployment 完成发布，超时后查看事件而不是无限等待\\\\u003c/span>\\\\nkubectl rollout status deployment/demo-web -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=120s\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查副本和 Service\\\\u003c/span>\\\\nkubectl get deployment,pods,service -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查 Service 对应的后端\\\\u003c/span>\\\\nkubectl get endpointslice -n demo -l kubernetes.io/service-name=demo-web\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅绑定本机端口；保持该终端运行，Ctrl+C 结束\\\\u003c/span>\\\\nkubectl port-forward -n demo service/demo-web 8080:80\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>另开终端验证：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 通过本机转发访问页面，预期包含 Hello Kubernetes\\\\u003c/span>\\\\ncurl --fail --max-time 5 http://127.0.0.1:8080/\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>port-forward 只验证选中的后端与转发通路，不能代替 Service 集群内转发、Ingress 和所有副本的验收。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"配置修改了应用为什么没变化\\\\\\">配置修改了，应用为什么没变化\\\\u003c/h2>\\\\n\\\\u003cp>环境变量从 ConfigMap 或 Secret 注入时，修改对象不会自动刷新已经运行的进程；使用挂载文件时，更新通常存在传播延迟，应用还需要重新读取文件。subPath 挂载也不能按普通目录挂载的更新行为判断。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看当前 ConfigMap，配置含敏感信息时不要直接外传\\\\u003c/span>\\\\nkubectl get configmap demo-web-content -n demo -o yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 从修改后的完整清单更新配置\\\\u003c/span>\\\\nkubectl apply -f demo-web.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 对依赖启动时读取配置的应用，安排一次滚动重启\\\\u003c/span>\\\\nkubectl rollout restart deployment/demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待重启完成\\\\u003c/span>\\\\nkubectl rollout status deployment/demo-web -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=120s\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>Secret 的 base64 表示不是加密。将业务密码通过受控的密钥管理流程注入，避免提交到公开仓库；读取 Secret 和创建 Secret 都应按需授予权限。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"滚动更新与健康检查\\\\\\">滚动更新与健康检查\\\\u003c/h2>\\\\n\\\\u003cp>发布前检查 readiness、startup、liveness 的作用以及应用实际健康接口。readiness 决定 Pod 是否接收 Service 流量；startup 可给慢启动应用留出时间；liveness 持续失败可能触发容器重启，不能简单把依赖暂时不可用都当成需要重启。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 Deployment 的更新策略和 Pod 模板\\\\u003c/span>\\\\nkubectl get deployment demo-api -n demo -o yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看更新进度\\\\u003c/span>\\\\nkubectl rollout status deployment/demo-api -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=120s\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查发布历史\\\\u003c/span>\\\\nkubectl rollout \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">history\\\\u003c/span> deployment/demo-api -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 对照业务指标确认失败后，回退到上一版本\\\\u003c/span>\\\\nkubectl rollout undo deployment/demo-api -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待回滚完成\\\\u003c/span>\\\\nkubectl rollout status deployment/demo-api -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=120s\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>优雅退出需要应用处理终止信号、停止接收新请求并完成在途请求；还应结合终止宽限期、负载均衡和长连接实测，不能只配置 preStop 就断言无损。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"更新时偶发-502连接重置\\\\\\">更新时偶发 502、连接重置\\\\u003c/h2>\\\\n\\\\u003cp>滚动更新的副本数量正常仍可能丢请求：端点状态传播、代理更新和容器退出是异步的。先记录故障时间，分别核对应用收到终止信号后的行为、代理日志和新副本的就绪时间。\\\\u003c/p>\\\\n\\\\u003cp>处理顺序：应用正确处理终止信号 → readiness 反映真实可服务状态 → 给在途请求足够的终止宽限期 → 必要时按实测传播时间配置 preStop → 用真实长连接和请求验证。preStop 消耗终止宽限期，不能只加一个很长的 sleep，却仍保留更短的宽限期。\\\\u003c/p>\\\\n\\\\u003cp>长连接通常不会在增加副本后自动迁移到新副本；先看连接分布和连接复用，按协议与客户端能力安排平滑重连。不要全局强制关闭长连接来替代容量分析。\\\\u003c/p>\\\\n\\\\u003cp>蓝绿发布通过切换版本入口快速回退；金丝雀按受控流量验证新版本；A/B 测试关注不同方案的业务效果。实施时记录路由规则、版本、成功率和回退目标，数据库变更仍需单独处理。控制器是否直接使用 Pod 端点、是否经过 Service IP，由具体实现与配置决定。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"扩容之后吞吐没有提高\\\\\\">扩容之后吞吐没有提高\\\\u003c/h2>\\\\n\\\\u003cp>先区分副本未创建、Pod 未调度、Pod 未就绪、流量未分配和下游已饱和。增加副本不能解决数据库锁竞争、共享限流或单分区瓶颈。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 Deployment 的期望和可用副本\\\\u003c/span>\\\\nkubectl get deployment demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看各副本节点分布和状态\\\\u003c/span>\\\\nkubectl get pods -n demo -l app=demo-web -o wide\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看自动扩缩容状态及限制，依赖已配置 HPA\\\\u003c/span>\\\\nkubectl get hpa -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查资源用量，依赖 Metrics API\\\\u003c/span>\\\\nkubectl top pods -n demo --containers\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>CPU requests 影响调度和部分 HPA 利用率计算；CPU limit 可能导致节流，内存 limit 则可能引发 OOM。不要把 requests 当成实际用量，也不要只看宿主机空闲就判断容器没有资源瓶颈。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"镜像拉取失败\\\\\\">镜像拉取失败\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>现象\\\\u003c/strong>：Pod 显示 \\\\u003ccode>ErrImagePull\\\\u003c/code> 或 \\\\u003ccode>ImagePullBackOff\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：查看 Pod → 读取事件中的具体错误 → 核对镜像名称、版本、仓库访问和凭据 → 修正声明文件 → 检查新 Pod。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看命名空间内 Pod 及所在节点\\\\u003c/span>\\\\nkubectl get pods -n demo -o wide\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看目标 Pod 的镜像和最近事件；替换 Pod 名\\\\u003c/span>\\\\nkubectl describe pod demo-api-xxxxx -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 Deployment 当前声明的镜像\\\\u003c/span>\\\\nkubectl get deployment demo-api -n demo -o jsonpath=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{.spec.template.spec.containers[*].image}&#x27;\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>例如事件提示 \\\\u003ccode>manifest unknown\\\\u003c/code>，先核对仓库中是否存在该镜像标签；提示认证失败时，检查 Pod 使用的镜像拉取 Secret。不要把凭据粘贴到日志或工单中。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 修正清单后，先检查本地文件与集群对象的差异\\\\u003c/span>\\\\nkubectl diff -f deployment.yaml -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认差异符合预期后应用清单\\\\u003c/span>\\\\nkubectl apply -f deployment.yaml -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看发布进度，等待新 Pod 就绪\\\\u003c/span>\\\\nkubectl rollout status deployment/demo-api -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=120s\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 复查 Pod 状态和重启次数\\\\u003c/span>\\\\nkubectl get pods -n demo -o wide\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>\\\\u003ccode>kubectl diff\\\\u003c/code> 发现差异时通常返回状态码 1，不一定是命令执行失败；权限或连接错误需单独检查。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"service-无法访问\\\\\\">Service 无法访问\\\\u003c/h2>\\\\n\\\\u003cp>\\\\u003cstrong>执行顺序\\\\u003c/strong>：确认 Pod 就绪 → 检查 Service 的 selector 和端口 → 查看 EndpointSlice → 在合适的网络位置分别测试 Pod 和 Service → 检查 DNS、网络策略和集群网络。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 Service、集群 IP 和端口\\\\u003c/span>\\\\nkubectl get service demo-api -n demo -o wide\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查选择器及 port、targetPort\\\\u003c/span>\\\\nkubectl describe service demo-api -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 Service 对应的后端地址和端口\\\\u003c/span>\\\\nkubectl get endpointslice -n demo -l kubernetes.io/service-name=demo-api -o wide\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看匹配示例标签的 Pod，标签需改为 Service 实际 selector\\\\u003c/span>\\\\nkubectl get pods -n demo -l app=demo-api -o wide --show-labels\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>例如 EndpointSlice 为空，先核对 Service selector 是否与 Pod 标签一致，并检查就绪状态；后端端口错误时核对 \\\\u003ccode>targetPort\\\\u003c/code> 和应用实际监听端口。Service 无 selector 或使用自定义 EndpointSlice 时，应结合其实际配置判断。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"ingress-与外部访问\\\\\\">Ingress 与外部访问\\\\u003c/h2>\\\\n\\\\u003cp>创建 Ingress 对象之前必须确认有对应的控制器，并指定匹配的 IngressClass。流量顺序按外部 DNS → 入口地址 → 控制器 → Service → EndpointSlice → Pod 检查。配置了 Ingress 不表示公网地址和证书会自动准备好。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看可用入口类\\\\u003c/span>\\\\nkubectl get ingressclass\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看业务入口地址、规则和事件\\\\u003c/span>\\\\nkubectl describe ingress demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对后端 Service 和端点\\\\u003c/span>\\\\nkubectl get service,endpointslice -n demo\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>HTTP 404 先确认 Host、路径和后端返回来源；502/503 结合控制器日志、端点就绪和后端监听排查。WebSocket、请求体大小和超时注解属于具体控制器能力，不能在不同产品之间直接照搬。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"给-web-示例添加域名入口\\\\\\">给 Web 示例添加域名入口\\\\u003c/h2>\\\\n\\\\u003cp>前提：已经部署入口控制器，且其 IngressClass 名称为 \\\\u003ccode>demo-gateway\\\\u003c/code>。先用 \\\\u003ccode>kubectl get ingressclass\\\\u003c/code> 核对名称，再把下列内容保存为 \\\\u003ccode>demo-web-ingress.yaml\\\\u003c/code>；域名需解析到控制器的实际入口地址。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-yaml\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 将示例域名的 HTTP 请求交给已有 demo-web Service\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">networking.k8s.io/v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">Ingress\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">namespace:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">spec:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">ingressClassName:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-gateway\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">rules:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">host:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">web.example.com\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">http:\\\\u003c/span>\\\\n        \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">paths:\\\\u003c/span>\\\\n          \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">path:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">pathType:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">Prefix\\\\u003c/span>\\\\n            \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">backend:\\\\u003c/span>\\\\n              \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">service:\\\\u003c/span>\\\\n                \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-web\\\\u003c/span>\\\\n                \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">port:\\\\u003c/span>\\\\n                  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">number:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-number\\\\\\">80\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 由服务端校验入口资源，前提是 demo 命名空间已经存在\\\\u003c/span>\\\\nkubectl apply --dry-run=server -f demo-web-ingress.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认控制器和域名配置后创建入口\\\\u003c/span>\\\\nkubectl apply -f demo-web-ingress.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看入口是否被控制器接管及相关事件\\\\u003c/span>\\\\nkubectl describe ingress demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 将文档示例地址替换为真实入口 IP，保留 HTTP Host 来测试路由\\\\u003c/span>\\\\ncurl --fail --max-time 5 --resolve web.example.com:80:192.0.2.10 http://web.example.com/\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>HTTPS 还需配置正确域名的证书及 TLS Secret；不要用跳过证书校验掩盖证书或路由错误。演示结束后按资源名删除该 Ingress。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"数据持久化与-statefulset\\\\\\">数据持久化与 StatefulSet\\\\u003c/h2>\\\\n\\\\u003cp>容器可写层不能作为可靠的数据存储。先确认存储类、访问模式、容量、拓扑和备份，再选择 PVC。ReadWriteOnce 不等于任意情况下只能被一个 Pod 使用，它主要约束单节点读写挂载；更严格的单 Pod 语义要检查存储插件是否支持对应模式。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看可用存储类及默认项\\\\u003c/span>\\\\nkubectl get storageclass\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查业务卷与绑定状态\\\\u003c/span>\\\\nkubectl get pvc -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 StatefulSet 副本、更新策略和卷声明\\\\u003c/span>\\\\nkubectl get statefulset -n demo -o yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查某个 PVC 绑定、挂载相关事件\\\\u003c/span>\\\\nkubectl describe pvc demo-data -n demo\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>数据库副本、持久卷副本和备份解决不同问题。使用 Rook/Ceph、数据库 Operator 或 Vitess 前，应验证其版本兼容性、仲裁与故障恢复；不要因“已有三副本”就跳过备份恢复演练。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"使用动态-pvc-保存数据\\\\\\">使用动态 PVC 保存数据\\\\u003c/h2>\\\\n\\\\u003cp>前提：集群有可用的默认 StorageClass，或在清单中填入已核对的 \\\\u003ccode>storageClassName\\\\u003c/code>；同时确认插件支持 ReadWriteOnce。保存为 \\\\u003ccode>demo-data.yaml\\\\u003c/code>：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-yaml\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 申请独立的 1Gi 持久卷，不将数据写入容器可写层\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">apiVersion:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">v1\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">kind:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">PersistentVolumeClaim\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">metadata:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-data\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">namespace:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">spec:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">accessModes:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">ReadWriteOnce\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">resources:\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">requests:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">storage:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">1Gi\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>在需要使用此数据的 Pod 模板中，向 \\\\u003ccode>spec.volumes\\\\u003c/code> 添加以下定义，再在对应容器的 \\\\u003ccode>volumeMounts\\\\u003c/code> 中挂载。不要把这两个字段写到错误层级：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-yaml\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 此处为 Pod spec 片段，需合并到实际模板，不是独立资源\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">volumes:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">data\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">persistentVolumeClaim:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">claimName:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">demo-data\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">containers:\\\\u003c/span>\\\\n  \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">app\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">image:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">your-registry.example.com/demo-api:tested-version\\\\u003c/span>\\\\n    \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">volumeMounts:\\\\u003c/span>\\\\n      \\\\u003cspan class=\\\\\\"hljs-bullet\\\\\\">-\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">name:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">data\\\\u003c/span>\\\\n        \\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">mountPath:\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">/var/lib/demo\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建 PVC，随后按实际工作负载模板挂载它\\\\u003c/span>\\\\nkubectl apply -f demo-data.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看绑定结果；WaitForFirstConsumer 模式需等待消费者调度\\\\u003c/span>\\\\nkubectl get pvc demo-data -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 未绑定或无法挂载时，查看事件而不是反复删除重建\\\\u003c/span>\\\\nkubectl describe pvc demo-data -n demo\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>只在实验数据可丢弃且已核对回收策略后清理 PVC。删除 PVC 可能触发底层卷删除；保留 PV 对象也不代表已经完成备份。hostPath 的同名路径属于不同节点，不能当成可随 Pod 迁移的共享存储。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"定时任务重复执行或没有执行\\\\\\">定时任务重复执行或没有执行\\\\u003c/h2>\\\\n\\\\u003cp>CronJob 创建 Job，再由 Job 创建 Pod。检查时沿 CronJob → Job → Pod 逐层定位，区别没有调度、调度后失败和任务还在运行。业务任务要有幂等控制，不能把调度当成恰好执行一次的保证。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看定时规则、暂停状态和上次调度时间\\\\u003c/span>\\\\nkubectl get cronjob -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看目标 CronJob 配置及事件\\\\u003c/span>\\\\nkubectl describe cronjob demo-report -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看已创建的任务及完成数量\\\\u003c/span>\\\\nkubectl get \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">jobs\\\\u003c/span> -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看某个 Job 创建的 Pod，标签按实际 Job 名替换\\\\u003c/span>\\\\nkubectl get pods -n demo -l batch.kubernetes.io/job-name=demo-report-12345\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看该 Job 的日志；多 Pod 或容器时进一步指定\\\\u003c/span>\\\\nkubectl logs -n demo job/demo-report-12345 --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>例如上一次任务运行超过调度周期，检查 concurrencyPolicy 是 Allow、Forbid 还是 Replace；没有执行则检查 suspend、时区、startingDeadlineSeconds 和控制器事件。需要人工补跑时先确认任务幂等及数据范围，再从 CronJob 创建独立 Job，不直接修改历史任务。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"helm-发布与回退\\\\\\">Helm 发布与回退\\\\u003c/h2>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>Helm 安装：Linux 二进制下载、校验与用户目录\\\\u003c/summary>\\\\n\\\\u003cp>在 \\\\u003ca href=\\\\\\"https://github.com/helm/helm/releases\\\\\\">Helm 发布页\\\\u003c/a> 选择与集群及 Chart 兼容的版本，并查看该版本的命令帮助。以下示例为 Linux amd64，其他架构替换包名。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 输入选定版本号，包含 v 前缀\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">read\\\\u003c/span> -r -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;Helm version: &#x27;\\\\u003c/span> HELM_VERSION\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 下载指定版本的官方二进制包\\\\u003c/span>\\\\ncurl --fail --location --output helm.tar.gz \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;https://get.helm.sh/helm-\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${HELM_VERSION}\\\\u003c/span>-linux-amd64.tar.gz&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 下载对应校验文件\\\\u003c/span>\\\\ncurl --fail --location --output helm.sha256sum \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;https://get.helm.sh/helm-\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${HELM_VERSION}\\\\u003c/span>-linux-amd64.tar.gz.sha256sum&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 提取校验值并校验本地文件；成功后才继续\\\\u003c/span>\\\\nawk \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{print $1 &quot;  helm.tar.gz&quot;}&#x27;\\\\u003c/span> helm.sha256sum | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha256sum\\\\u003c/span> --check\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 在独立临时目录解包，避免覆盖现有文件\\\\u003c/span>\\\\nhelm_unpack=$(\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mktemp\\\\u003c/span> -d)\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解开已校验的包\\\\u003c/span>\\\\n tar -xzf helm.tar.gz -C \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$helm_unpack\\\\u003c/span>&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建用户可执行目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 安装已校验的可执行文件\\\\u003c/span>\\\\ninstall -m 0755 \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$helm_unpack\\\\u003c/span>/linux-amd64/helm&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin/helm&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 为当前终端添加 PATH\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> PATH=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin:\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PATH\\\\u003c/span>&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查版本与帮助\\\\u003c/span>\\\\nhelm version\\\\nhelm upgrade --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">help\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>下载或校验失败应停止，不继续解包安装。安装不需要集群管理员权限，发布应用时仍受 kubeconfig 和 RBAC 限制。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003cp>使用与当前集群兼容的 Helm 版本。旧教程中的 Tiller 和 Helm 2 初始化步骤不适用于常见的 Helm 3 工作流。Chart 来源、依赖、默认权限与持久卷行为都应在安装前检查。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看本机 Helm 版本，前提是已安装\\\\u003c/span>\\\\nhelm version\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 在本地 chart 目录执行基本检查\\\\u003c/span>\\\\nhelm lint ./demo-chart\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 渲染资源清单，检查命名空间、镜像和权限；输出可能包含 Secret\\\\u003c/span>\\\\nhelm template demo-web ./demo-chart -n demo -f values.yaml\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认后安装或更新；等待资源就绪，超时退出\\\\u003c/span>\\\\nhelm upgrade --install demo-web ./demo-chart -n demo -f values.yaml --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">wait\\\\u003c/span> --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span> 5m\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看发布历史\\\\u003c/span>\\\\nhelm \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">history\\\\u003c/span> demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认回退目标后回滚到指定 revision\\\\u003c/span>\\\\nhelm rollback demo-web 1 -n demo --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">wait\\\\u003c/span> --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span> 5m\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>应用回退不等于数据库结构和数据回退。发布前检查迁移脚本和向后兼容性，回退后仍需验证业务读写、错误率与数据完整性。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"发布验收与清理\\\\\\">发布验收与清理\\\\u003c/h2>\\\\n\\\\u003cp>检查所有副本的就绪与重启次数、实际业务请求、错误率、日志、端点和外部访问。就绪成功是条件之一，不能替代业务验收。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只读检查应用副本与节点分布\\\\u003c/span>\\\\nkubectl get pods -n demo -l app=demo-web -o wide\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看各副本近期日志\\\\u003c/span>\\\\nkubectl logs -n demo -l app=demo-web --all-containers --prefix --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=50\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 演示结束后只删除本例的 Deployment 和 Service\\\\u003c/span>\\\\nkubectl delete deployment/demo-web service/demo-web -n demo\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 删除本例的首页配置\\\\u003c/span>\\\\nkubectl delete configmap/demo-web-content -n demo\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>保留命名空间，清理前核对同名对象是否属于本次实验。\\\\u003c/p>\\\\n\\\\u003cp>相关速查：\\\\u003ca href=\\\\\\"kubernetes-operations-commands.html\\\\\\">Kubernetes 常用运维命令\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"发布前确认环境\\",\\"level\\":2,\\"id\\":\\"发布前确认环境\\"},{\\"title\\":\\"清单字段不熟悉时，直接查集群支持的 API\\",\\"level\\":2,\\"id\\":\\"清单字段不熟悉时直接查集群支持的-api\\"},{\\"title\\":\\"资源对象怎么选择\\",\\"level\\":2,\\"id\\":\\"资源对象怎么选择\\"},{\\"title\\":\\"运行一个完整的 Web 示例\\",\\"level\\":2,\\"id\\":\\"运行一个完整的-web-示例\\"},{\\"title\\":\\"配置修改了，应用为什么没变化\\",\\"level\\":2,\\"id\\":\\"配置修改了应用为什么没变化\\"},{\\"title\\":\\"滚动更新与健康检查\\",\\"level\\":2,\\"id\\":\\"滚动更新与健康检查\\"},{\\"title\\":\\"更新时偶发 502、连接重置\\",\\"level\\":2,\\"id\\":\\"更新时偶发-502连接重置\\"},{\\"title\\":\\"扩容之后吞吐没有提高\\",\\"level\\":2,\\"id\\":\\"扩容之后吞吐没有提高\\"},{\\"title\\":\\"镜像拉取失败\\",\\"level\\":2,\\"id\\":\\"镜像拉取失败\\"},{\\"title\\":\\"Service 无法访问\\",\\"level\\":2,\\"id\\":\\"service-无法访问\\"},{\\"title\\":\\"Ingress 与外部访问\\",\\"level\\":2,\\"id\\":\\"ingress-与外部访问\\"},{\\"title\\":\\"给 Web 示例添加域名入口\\",\\"level\\":2,\\"id\\":\\"给-web-示例添加域名入口\\"},{\\"title\\":\\"数据持久化与 StatefulSet\\",\\"level\\":2,\\"id\\":\\"数据持久化与-statefulset\\"},{\\"title\\":\\"使用动态 PVC 保存数据\\",\\"level\\":2,\\"id\\":\\"使用动态-pvc-保存数据\\"},{\\"title\\":\\"定时任务重复执行或没有执行\\",\\"level\\":2,\\"id\\":\\"定时任务重复执行或没有执行\\"},{\\"title\\":\\"Helm 发布与回退\\",\\"level\\":2,\\"id\\":\\"helm-发布与回退\\"},{\\"title\\":\\"发布验收与清理\\",\\"level\\":2,\\"id\\":\\"发布验收与清理\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/kubernetes-application-practice.md","filePath":"articles/kubernetes-application-practice.md"}'),n={name:"articles/kubernetes-application-practice.md"};function e(u,l,t,p,o,r){return c(),a("div")}const h=s(n,[["render",e]]);export{m as __pageData,h as default};
